/**
 * pybytes.mjs
 *
 * Reproduces the exact string that Python's repr() of a `bytes` object
 * produces (i.e. what `print(b'...')` shows).
 *
 * Rules (mirroring CPython's bytes_repr in Objects/bytesobject.c):
 *  - Prefix `b`.
 *  - Quote selection: single quote by default; double quote if the data
 *    contains a single quote (') but no double quote (").
 *  - Printable ASCII bytes (0x20-0x7E) are shown literally, except the
 *    backslash and the active quote character, which are backslash-escaped.
 *  - \t -> "\\t", \n -> "\\n", \r -> "\\r".
 *  - All other bytes are shown as "\xNN" with lowercase hex digits.
 */

const BACKSLASH = 0x5c; // '\\'
const SINGLE_QUOTE = 0x27; // '\''
const DOUBLE_QUOTE = 0x22; // '"'
const TAB = 0x09;
const NEWLINE = 0x0a;
const CR = 0x0d;
const PRINTABLE_MIN = 0x20;
const PRINTABLE_MAX = 0x7e;

const HEX = '0123456789abcdef';

/**
 * Return the exact string Python's repr() of a bytes object would produce.
 *
 * @param {Uint8Array} bytes - The raw bytes to represent.
 * @returns {string} The Python-style bytes repr, e.g. b'abc\x00\xff'.
 */
export function pyBytesRepr(bytes) {
  if (!(bytes instanceof Uint8Array)) {
    throw new TypeError('pyBytesRepr expects a Uint8Array');
  }

  // Determine the quote character the way CPython does: prefer a single
  // quote, but switch to a double quote if the data contains a single
  // quote and no double quote (so the single quote needs no escaping).
  let hasSingle = false;
  let hasDouble = false;
  for (let i = 0; i < bytes.length; i++) {
    if (bytes[i] === SINGLE_QUOTE) hasSingle = true;
    else if (bytes[i] === DOUBLE_QUOTE) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const quoteByte = quote === '"' ? DOUBLE_QUOTE : SINGLE_QUOTE;

  let out = 'b' + quote;
  for (let i = 0; i < bytes.length; i++) {
    const c = bytes[i];
    if (c === quoteByte || c === BACKSLASH) {
      out += '\\' + String.fromCharCode(c);
    } else if (c === TAB) {
      out += '\\t';
    } else if (c === NEWLINE) {
      out += '\\n';
    } else if (c === CR) {
      out += '\\r';
    } else if (c >= PRINTABLE_MIN && c <= PRINTABLE_MAX) {
      out += String.fromCharCode(c);
    } else {
      out += '\\x' + HEX[(c >> 4) & 0xf] + HEX[c & 0xf];
    }
  }
  out += quote;
  return out;
}

/**
 * ecb_mode.mjs
 *
 * AES in ECB (Electronic Codebook) mode, mirroring pyaes'
 * AESModeOfOperationECB: each 16-byte block is encrypted/decrypted
 * independently with the raw block cipher. No padding is applied; the
 * data length must already be a multiple of the 16-byte block size.
 */

import { aesEncryptBlock, aesDecryptBlock } from './aes_core.mjs';

const BLOCK_SIZE = 16;

function checkKeySize(key) {
  if (!(key instanceof Uint8Array)) {
    throw new Error('Invalid key size');
  }
  const len = key.length;
  if (len !== 16 && len !== 24 && len !== 32) {
    throw new Error('Invalid key size');
  }
}

function checkDataLength(data) {
  if (!(data instanceof Uint8Array)) {
    throw new Error('Data length must be a multiple of 16 bytes');
  }
  if (data.length % BLOCK_SIZE !== 0) {
    throw new Error('Data length must be a multiple of 16 bytes');
  }
}

export class AESModeOfOperationECB {
  /**
   * @param {Uint8Array} keyBytes - 16, 24, or 32 byte key.
   * @throws {Error} "Invalid key size" for any other key length.
   */
  constructor(keyBytes) {
    checkKeySize(keyBytes);
    this.key = keyBytes;
  }

  /**
   * Encrypt data (length must be a multiple of 16 bytes).
   * @param {Uint8Array} dataBytes
   * @returns {Uint8Array} ciphertext, same length as input.
   */
  encrypt(dataBytes) {
    checkDataLength(dataBytes);
    const out = new Uint8Array(dataBytes.length);
    for (let offset = 0; offset < dataBytes.length; offset += BLOCK_SIZE) {
      const block = dataBytes.subarray(offset, offset + BLOCK_SIZE);
      out.set(aesEncryptBlock(this.key, block), offset);
    }
    return out;
  }

  /**
   * Decrypt data (length must be a multiple of 16 bytes).
   * @param {Uint8Array} dataBytes
   * @returns {Uint8Array} plaintext, same length as input.
   */
  decrypt(dataBytes) {
    checkDataLength(dataBytes);
    const out = new Uint8Array(dataBytes.length);
    for (let offset = 0; offset < dataBytes.length; offset += BLOCK_SIZE) {
      const block = dataBytes.subarray(offset, offset + BLOCK_SIZE);
      out.set(aesDecryptBlock(this.key, block), offset);
    }
    return out;
  }
}

import { pyBytesRepr } from '/output/pybytes.mjs';
import { execFileSync } from 'node:child_process';

function pyRepr(bytes) {
  // Ask real Python for repr(bytes(list)).
  const list = Array.from(bytes).join(',');
  const src = `import sys; sys.stdout.write(repr(bytes([${list}])))`;
  return execFileSync('python3', ['-c', src], { encoding: 'utf8' });
}

const cases = [
  ['empty', new Uint8Array([])],
  ['single quote only', new Uint8Array([0x27])],           // -> b"'"
  ['double quote only', new Uint8Array([0x22])],           // -> b'"'
  ['both quotes', new Uint8Array([0x27, 0x22, 0x27])],     // -> b'\'"\''
  ['backslash', new Uint8Array([0x5c])],                   // -> b'\\'
  ['backslash + single quote', new Uint8Array([0x5c, 0x27])], // -> b"\\'"
  ['tab', new Uint8Array([0x09])],
  ['newline', new Uint8Array([0x0a])],
  ['carriage return', new Uint8Array([0x0d])],
  ['boundary 0x1f', new Uint8Array([0x1f])],
  ['boundary 0x20', new Uint8Array([0x20])],
  ['boundary 0x7e', new Uint8Array([0x7e])],
  ['boundary 0x7f', new Uint8Array([0x7f])],
  ['printable range', new Uint8Array([0x21, 0x41, 0x7a])],
  ['high bytes', new Uint8Array([0x00, 0x80, 0xff])],
  ['all 256 byte values', new Uint8Array(Array.from({ length: 256 }, (_, i) => i))],
  // the sample ciphertext from the reference output
  ['sample ct 1', new Uint8Array([0x02, 0x7d, 0xa7, 0x99, 0xf5, 0x27, 0x34, 0x42, 0xbd, 0x80, 0xde, 0xd1, 0x80, 0x28, 0x82, 0xf2])],
  ['sample ct 2', new Uint8Array([0xd1, 0x4d, 0xe6, 0x8e, 0x78, 0x3b, 0xc7, 0x97, 0xe1, 0x6c, 0xd9, 0x6d, 0x56, 0x79, 0x56, 0x95])],
  ['sample plaintext', new TextEncoder().encode('^Z-jz9z*elH|LaA0')],
];

let failed = 0;
for (const [name, bytes] of cases) {
  const js = pyBytesRepr(bytes);
  const py = pyRepr(bytes);
  const ok = js === py;
  if (!ok) failed++;
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}`);
  console.log(`   js: ${js}`);
  if (!ok) console.log(`   py: ${py}`);
}
if (failed) {
  console.log(`\n${failed} case(s) FAILED`);
  process.exit(1);
}
console.log('\nAll cases match Python repr().');

// Test stub for aes_core: identity permutation, encrypt = decrypt = copy.
// Lets us verify the ECB wrapper's block loop and validation logic
// independently of the real AES implementation.
export function aesEncryptBlock(key, block) {
  if (![16, 24, 32].includes(key.length)) throw new Error('Invalid key size');
  return Uint8Array.from(block, (b) => b ^ 0xa5);
}

export function aesDecryptBlock(key, block) {
  if (![16, 24, 32].includes(key.length)) throw new Error('Invalid key size');
  return Uint8Array.from(block, (b) => b ^ 0xa5);
}

import assert from 'node:assert/strict';
import { AESModeOfOperationECB } from './ecb_mode.mjs';

// valid key sizes
for (const size of [16, 24, 32]) {
  assert.doesNotThrow(() => new AESModeOfOperationECB(new Uint8Array(size)), `key ${size}`);
}
// invalid key sizes
for (const size of [0, 8, 15, 17, 31, 33, 64]) {
  assert.throws(() => new AESModeOfOperationECB(new Uint8Array(size)), /^Error: Invalid key size$/, `key ${size}`);
}

const key = new TextEncoder().encode('QU$h{ecq^#qb{L3M'); // 16 bytes
const ecb = new AESModeOfOperationECB(key);

// single block
const block = new TextEncoder().encode('^Z-jz9z*elH|LaA0'); // 16 bytes
const ct = ecb.encrypt(block);
assert.equal(ct.length, 16);
assert.deepEqual(ct, Uint8Array.from(block, (b) => b ^ 0xa5), 'encrypt xors each block');
// input not mutated / result is a copy
assert.deepEqual(block, new TextEncoder().encode('^Z-jz9z*elH|LaA0'), 'input untouched');

// decrypt round-trips (stub is involutive)
const pt = ecb.decrypt(ct);
assert.deepEqual(pt, block, 'decrypt round-trips');

// multi-block (48 bytes = 3 blocks)
const multi = new Uint8Array(48).map((_, i) => i);
const ctMulti = ecb.encrypt(multi);
assert.equal(ctMulti.length, 48);
assert.deepEqual(ecb.decrypt(ctMulti), multi, 'multi-block round-trip');

// empty data is allowed (0 % 16 === 0)
assert.equal(ecb.encrypt(new Uint8Array(0)).length, 0, 'empty input ok');

// bad data lengths
for (const len of [1, 8, 15, 17, 31]) {
  assert.throws(() => ecb.encrypt(new Uint8Array(len)), /^Error: Data length must be a multiple of 16 bytes$/, `enc len ${len}`);
  assert.throws(() => ecb.decrypt(new Uint8Array(len)), /^Error: Data length must be a multiple of 16 bytes$/, `dec len ${len}`);
}

console.log('All ECB wrapper tests passed.');
